<script setup>
import { computed, ref, watch } from 'vue'
import { ElMessage } from 'element-plus'
import { state, submitUsageRequest, checkGovernance, allowed, notify, downloadVersion } from '../store'
import { buildDatasetTrace, contentFieldsFor, qualityFingerprint, isDatasetVersion, canDownload, uid, now, isDatasetOwner, isVersionAuthorized } from '../domain'
import FormDialog from './FormDialog.vue'
const executionText = value => ['待后端落实','待后端保障'].includes(value) ? '—' : value==='后端保障'?'系统策略':value
const props = defineProps({ page: String })
const emit = defineEmits(['navigate'])
const search = ref('')
const descriptionOverflow = ref({})
const descriptionObservers = new WeakMap()
function measureDescription(element, id) {
  const overflow = element.scrollHeight > element.clientHeight + 1
  if (descriptionOverflow.value[id] !== overflow) descriptionOverflow.value[id] = overflow
}
const vDescriptionOverflow = {
  mounted(element, binding) {
    const observer = new ResizeObserver(() => measureDescription(element, binding.value))
    descriptionObservers.set(element, observer)
    observer.observe(element)
    measureDescription(element, binding.value)
  },
  updated(element, binding) { measureDescription(element, binding.value) },
  unmounted(element) { descriptionObservers.get(element)?.disconnect(); descriptionObservers.delete(element) },
}
const selectedType = ref('')
const selectedIndustry = ref('')
const sortBy = ref('updated')
const plazaPage = ref(1)
const scope = ref('全部')
watch([search, selectedType, selectedIndustry, sortBy, () => scope.value, () => state.role], () => { plazaPage.value = 1 })
const descriptionFor = dataset => dataset.introduction || dataset.demand || dataset.scene || ''
const selected = ref(null)
const versionId = ref('')
const dialog = ref(false)
const requestVersion = ref(null)
const formOpen = ref(false)
const requestFields = [{ key: 'applicant', label: '申请人', required: true }, { key: 'department', label: '部门', required: true }, { key: 'reason', label: '使用理由', required: true, type: 'textarea' }]
const owned = d => isDatasetOwner(d, state.role)
const versionApproved = version => isVersionAuthorized(version, state.requests, state.role, state.datasets.find(d => d.id === version.datasetId))
const authorizedVersions = id => state.versions.filter(v => v.datasetId === id && isDatasetVersion(v) && v.status === '已发布' && versionApproved(v))
const approved = id => authorizedVersions(id).length > 0
const versionsFor = id => state.versions.filter(v => v.datasetId === id && isDatasetVersion(v) && (props.page === 'plaza' || !owned(state.datasets.find(d=>d.id===id)) ? v.status === '已发布' : true)).sort((a,b)=>b.number-a.number)
const latestReleaseFor = dataset => versionsFor(dataset.id).find(version => version.status === '已发布')
const downloadsFor = dataset => latestReleaseFor(dataset) ? (dataset.downloads || 0) : 0
const publisherFor = dataset => dataset.publisherId || versionsFor(dataset.id).find(version => version.status === '已发布')?.release?.publisher || dataset.owner || '管理员'
const plazaDatasets = computed(() => state.datasets.filter(dataset => allowed('view',dataset.id) && dataset.storageState!=='已归档' && versionsFor(dataset.id).length))
const datasetTypes = computed(() => [...new Set(plazaDatasets.value.map(dataset => dataset.type))])
const datasetIndustries = computed(() => [...new Set(plazaDatasets.value.map(dataset => dataset.industry || dataset.project).filter(Boolean))])
const publishedTimeFor = dataset => { const version = latestReleaseFor(dataset); return version?.release?.publishedAt || version?.published || version?.created || '' }
const updatedTime = dataset => Date.parse(publishedTimeFor(dataset).replaceAll('/','-').replace(' ','T')) || 0
const publishedLabelFor = dataset => { const date = publishedTimeFor(dataset).match(/^(\d{4})[\/-](\d{1,2})[\/-](\d{1,2})/); return date ? `发布于：${date[1]}年${Number(date[2])}月${Number(date[3])}日` : '—' }
const datasets = computed(() => {
  const rows = state.datasets.filter(dataset => allowed('view',dataset.id) && `${dataset.name} ${dataset.code || ''}`.toLowerCase().includes(search.value.trim().toLowerCase()) && (props.page === 'plaza' ? dataset.storageState!=='已归档' && versionsFor(dataset.id).length : owned(dataset) || approved(dataset.id)) && (props.page === 'plaza' || scope.value === '全部' || (scope.value === '我的数据集' ? owned(dataset) : approved(dataset.id))))
  if (props.page !== 'plaza') return rows
  return rows.filter(dataset => (!selectedType.value || dataset.type === selectedType.value) && (!selectedIndustry.value || (dataset.industry || dataset.project) === selectedIndustry.value)).sort((a,b) => sortBy.value === 'downloads' ? (b.downloads || 0) - (a.downloads || 0) || updatedTime(b) - updatedTime(a) : updatedTime(b) - updatedTime(a) || (b.downloads || 0) - (a.downloads || 0))
})
watch(() => datasets.value.length, total => { plazaPage.value = Math.min(plazaPage.value, Math.max(1, Math.ceil(total / 10))) })
const versions = computed(() => selected.value ? versionsFor(selected.value.id) : [])
const version = computed(() => versions.value.find(v=>v.id===versionId.value))
const detailFields=computed(()=>contentFieldsFor(state,selected.value))
const detailReport=computed(()=>state.qualityReports.find(report=>report.versionId===version.value?.id))
const trace=computed(()=>selected.value && version.value?buildDatasetTrace(state,selected.value.id,version.value.id):[])
const versionExecutions=computed(()=>state.governanceChecks.filter(item=>item.datasetId===selected.value?.id && (item.versionId===version.value?.id || !item.versionId)))
const usageEvents=computed(()=>state.usageEvents.filter(item=>item.versionId===version.value?.id))
const reportCurrent=computed(()=>detailReport.value && detailReport.value.fingerprint===qualityFingerprint(state,version.value))
const downloadable = computed(() => version.value && allowed('download',version.value.datasetId) && canDownload(version.value,state.requests,state.role,selected.value))
function open(dataset) { selected.value=dataset; versionId.value=versionsFor(dataset.id)[0]?.id || ''; dialog.value=true }
function editDataset() { state.activeProject=selected.value.projectId; state.activeDataset=selected.value.id; state.focusVersion=versionId.value; dialog.value=false; emit('navigate','versions') }
function apply() {
  if (owned(selected.value)) return
  if (state.requests.some(r=>r.versionId===version.value.id && r.user===state.role && r.status==='待审批')) return ElMessage.warning('此版本已有待审批申请')
  requestVersion.value=version.value; formOpen.value=true
}
function submit(data) { if (submitUsageRequest(requestVersion.value,data)) formOpen.value=false }

</script>
<template>
  <section v-if="page==='plaza'" class="plaza-discovery">
    <div class="plaza-search"><el-input v-model="search" placeholder="搜索数据集名称或编号" aria-label="搜索数据集名称或编号" clearable><template #prefix><el-icon><Search /></el-icon></template></el-input></div>
    <div class="plaza-controls"><div class="plaza-filters"><el-select v-model="selectedType" placeholder="全部类型" aria-label="数据集类型" clearable><template #prefix><el-icon><Files /></el-icon></template><el-option v-for="type in datasetTypes" :key="type" :label="type" :value="type" /></el-select><el-select v-model="selectedIndustry" placeholder="全部领域" aria-label="数据集领域" clearable><template #prefix><el-icon><Grid /></el-icon></template><el-option v-for="industry in datasetIndustries" :key="industry" :label="industry" :value="industry" /></el-select></div>
    <div class="plaza-sorting" role="group" aria-label="数据集排序"><button :class="{active:sortBy==='updated'}" :aria-pressed="sortBy==='updated'" @click="sortBy='updated'"><el-icon><Clock /></el-icon>最新更新</button><button :class="{active:sortBy==='downloads'}" :aria-pressed="sortBy==='downloads'" @click="sortBy='downloads'"><el-icon><Download /></el-icon>最多下载</button></div></div>
  </section>
  <section v-else class="directory-toolbar"><div class="toolbar"><el-input v-model="search" placeholder="搜索数据集名称或编号" clearable><template #prefix><el-icon><Search /></el-icon></template></el-input><el-radio-group v-if="page==='catalog'" v-model="scope"><el-radio-button v-for="name in ['全部','我的数据集','已获授权']" :key="name" :value="name">{{ name }}</el-radio-button></el-radio-group><span class="toolbar-spacer"></span><span class="muted">{{ datasets.length }} 个数据集</span></div></section>
  <div v-if="datasets.length" class="recommendation-table-wrap plaza-list"><table class="recommendation-table plaza-table"><thead><tr><th scope="col">数据集名称</th><th scope="col">类型</th><th scope="col">领域</th><th scope="col">发布者</th><th scope="col" class="numeric">版本数</th><th scope="col" class="numeric">下载量</th></tr></thead><tbody><tr v-for="dataset in datasets.slice((plazaPage - 1) * 10, plazaPage * 10)" :key="dataset.id"><td><button class="recommendation-name" @click="open(dataset)"><el-icon :class="dataset.coverTone || 'blue'"><component :is="dataset.coverIcon || (dataset.type==='图片'?'PictureFilled':dataset.type==='问答对'?'ChatDotRound':'Reading')" /></el-icon><span>{{ dataset.name }}</span><el-tag v-if="latestReleaseFor(dataset)" size="small" type="info" class="plaza-version-tag">{{ latestReleaseFor(dataset).release?.tag || `V${latestReleaseFor(dataset).number}` }}</el-tag><el-tag v-else-if="owned(dataset) && dataset.storageState!=='已归档'" size="small" type="warning" class="plaza-version-tag">待发布</el-tag><el-tag v-if="dataset.storageState==='已归档'" type="info" size="small">已归档</el-tag></button><div class="plaza-introduction" :class="{'is-complete':descriptionOverflow[dataset.id] === false}"><div v-if="page==='catalog'" class="catalog-access-tags tags"><el-tag v-if="owned(dataset)" type="primary"><el-icon><FolderOpened /></el-icon>我的数据集</el-tag><el-tag v-else-if="approved(dataset.id)" type="success"><el-icon><CircleCheck /></el-icon>已获授权 · {{ authorizedVersions(dataset.id).length }} 个版本</el-tag></div><p v-description-overflow="dataset.id" class="plaza-description">{{ descriptionFor(dataset) }}</p><div class="plaza-description-footer"><button v-if="descriptionOverflow[dataset.id]" class="plaza-description-toggle" @click="open(dataset)">详情<el-icon><ArrowRight /></el-icon></button><time v-if="publishedTimeFor(dataset)" class="plaza-release-time" :datetime="publishedTimeFor(dataset).replaceAll('/','-').replace(' ','T')"><el-icon><Clock /></el-icon>{{ publishedLabelFor(dataset) }}</time></div></div></td><td>{{ dataset.type }}</td><td>{{ dataset.industry || dataset.project }}</td><td>{{ publisherFor(dataset) }}</td><td class="numeric">{{ versionsFor(dataset.id).length }}</td><td class="numeric"><span class="dataset-downloads" aria-label="下载量"><el-icon><Download /></el-icon>{{ downloadsFor(dataset).toLocaleString() }}</span></td></tr></tbody></table></div>

  <el-pagination v-if="datasets.length" v-model:current-page="plazaPage" :page-size="10" :pager-count="5" :total="datasets.length" layout="total, prev, pager, next" :aria-label="page==='catalog'?'数据目录分页':'数据广场分页'" class="plaza-pagination" />
  <section v-if="!datasets.length" class="panel"><el-empty :description="page==='catalog'?'暂无自己的或已获准使用的数据集':(search || selectedType || selectedIndustry ? '没有匹配的数据集' : '暂无已发布的共享数据集')"><el-button v-if="page==='catalog'" type="primary" @click="$emit('navigate','plaza')"><el-icon><Grid /></el-icon>去数据广场</el-button></el-empty></section>
  <el-drawer v-model="dialog" :title="selected?.name" size="min(880px, 96vw)"><template v-if="selected"><div class="detail-badges"><el-tag>{{ selected.type }}</el-tag><el-tag type="info">{{ selected.project }}</el-tag><el-tag v-if="approved(selected.id)" type="success"><el-icon><CircleCheck /></el-icon>已获授权 · {{ authorizedVersions(selected.id).length }} 个版本</el-tag></div><el-descriptions :column="1" border><el-descriptions-item label="数据集编号">{{ selected.code }}</el-descriptions-item><el-descriptions-item label="数据来源">{{ selected.source || '—' }}</el-descriptions-item><el-descriptions-item label="所属领域">{{ selected.industry }}</el-descriptions-item><el-descriptions-item label="数据等级">{{ selected.level }}</el-descriptions-item><el-descriptions-item label="数据责任人">{{ selected.steward }}</el-descriptions-item><el-descriptions-item label="内容标准">{{ state.fieldTemplates.find(item=>item.id===selected.fieldTemplateId)?.name || '未绑定' }}</el-descriptions-item></el-descriptions><div class="dataset-downloads dataset-detail-downloads"><el-icon><Download /></el-icon>下载量 {{ downloadsFor(selected).toLocaleString() }}</div><p class="dataset-introduction">{{ descriptionFor(selected) }}</p><div class="tags"><el-tag v-for="tag in selected.tags" :key="tag">{{ tag }}</el-tag></div><el-divider /><el-collapse class="dataset-history">
    <el-collapse-item name="trace" title="来源与流转"><el-timeline v-if="trace.length"><el-timeline-item v-for="item in trace" :key="item.id" :timestamp="item.time" placement="top"><h4><el-icon><component :is="item.icon" /></el-icon>{{ item.name.replace(/ · 待后端保障$/, '') }}</h4><p>{{ item.detail }}</p><span v-if="item.actor">{{ item.actor }}</span></el-timeline-item></el-timeline><el-empty v-else description="此版本尚无可追溯记录" /></el-collapse-item>
    <el-collapse-item name="evidence" title="发布依据"><template v-if="version?.release?.evidence"><div class="detail-badges"><span>{{ version.release.evidence.operator }} · {{ version.release.evidence.created }}</span></div><el-descriptions :column="2" border><el-descriptions-item label="数据集编号">{{ version.release.evidence.metadata.code }}</el-descriptions-item><el-descriptions-item label="数据等级">{{ version.release.evidence.metadata.level }}</el-descriptions-item><el-descriptions-item label="来源">{{ version.release.evidence.metadata.source }}</el-descriptions-item><el-descriptions-item label="责任人">{{ version.release.evidence.metadata.steward }}</el-descriptions-item><el-descriptions-item label="内容标准">{{ version.release.evidence.contentTemplate?.name || '未绑定' }} r{{ version.release.evidence.contentTemplate?.revision || '—' }}</el-descriptions-item><el-descriptions-item label="质量报告">{{ state.qualityReports.find(report=>report.id===version.release.evidence.qualityReportId)?.created || '未记录' }}</el-descriptions-item></el-descriptions><el-table :data="version.release.evidence.standards"><el-table-column label="采用标准" prop="name" /><el-table-column label="修订" width="90"><template #default="{row}">r{{ row.revision }}</template></el-table-column><el-table-column label="执行方式"><template #default="{row}">{{ executionText(row.executionMode) }}</template></el-table-column><el-table-column label="确认依据" min-width="200"><template #default="{row}">{{ row.confirmation?row.confirmation.operator+' · '+row.confirmation.note:executionText(row.result) || '—' }}</template></el-table-column><el-table-column label="字段 / 环节"><template #default="{row}">{{ row.field || row.stages?.join('、') || '成果存储' }}</template></el-table-column></el-table></template><el-empty v-else :description="version?.release?'此历史发布未记录执行依据':'此版本尚未发布'" /></el-collapse-item>
    <el-collapse-item name="executions" title="规范执行记录"><el-table :data="versionExecutions" max-height="360"><el-table-column type="expand"><template #default="{row}"><el-table :data="row.standards || []"><el-table-column label="标准" prop="name" /><el-table-column label="修订" width="80"><template #default="{row}">r{{ row.revision }}</template></el-table-column><el-table-column label="执行方式"><template #default="{row}">{{ executionText(row.executionMode) }}</template></el-table-column><el-table-column label="结果" ><template #default="{row}">{{ executionText(row.result) }}</template></el-table-column></el-table></template></el-table-column><el-table-column label="环节" prop="stage" width="90" /><el-table-column label="对象"><template #default="{row}">{{ row.versionId?'V'+state.versions.find(item=>item.id===row.versionId)?.number:row.sourceName || '数据集级' }}</template></el-table-column><el-table-column label="操作人" prop="operator" width="100" /><el-table-column label="结果" width="110"><template #default="{row}">{{ executionText(row.status) }}</template></el-table-column><el-table-column label="时间" prop="created" width="180" /></el-table></el-collapse-item>
    <el-collapse-item name="usage" title="申请与使用"><el-table :data="state.requests.filter(item=>item.versionId===version?.id)" max-height="240"><el-table-column label="申请人" prop="applicant" /><el-table-column label="使用理由" prop="reason" min-width="200" /><el-table-column label="状态" prop="status" /><el-table-column label="审批意见" prop="note" min-width="180" /><el-table-column label="申请时间" prop="created" width="180" /><el-table-column label="审批时间" prop="approved" width="180" /></el-table><el-table :data="usageEvents" max-height="280"><el-table-column label="操作" prop="action" /><el-table-column label="用户" prop="user" /><el-table-column label="状态" prop="status" /><el-table-column label="说明" prop="detail" min-width="200" /><el-table-column label="时间" prop="created" width="180" /></el-table></el-collapse-item><el-collapse-item name="fields" title="字段字典"><el-table :data="detailFields"><el-table-column label="字段" prop="field" min-width="150" /><el-table-column label="含义" prop="name" min-width="120" /><el-table-column label="类型" prop="type" width="80" /><el-table-column label="单位" prop="unit" width="80" /><el-table-column label="约束" min-width="180"><template #default="{row}">{{ [row.required?'必填':'',row.unique?'唯一':'',row.checkRange?`${row.min}—${row.max}`:'',row.allowedValues || ''].filter(Boolean).join('、') }}</template></el-table-column></el-table></el-collapse-item><el-collapse-item name="quality" title="质量报告"><template v-if="detailReport"><div class="detail-badges"><el-tag>V{{ detailReport.versionNumber }}</el-tag><el-tag :type="detailReport.issues.some(issue=>issue.severity==='阻断' && !(issue.kind==='manual' && issue.status==='已确认'))?'warning':'success'">{{ detailReport.issues.length }}个检查问题</el-tag><el-tag v-if="!reportCurrent" type="warning">内容或规则已变更</el-tag></div><p>检查{{ detailReport.total }}条 · 通过{{ detailReport.passed }}条 · {{ detailReport.templateName }} · {{ detailReport.created }}</p><el-table :data="detailReport.rules"><el-table-column label="检查字段" prop="name" /><el-table-column label="执行规则" min-width="230"><template #default="{row}">{{ [row.required?'必填':'',row.type,row.unique?'唯一':'',row.checkRange?`${row.min}—${row.max}${row.unit || ''}`:'',row.allowedValues?'允许值：'+row.allowedValues:''].filter(Boolean).join('、') }}</template></el-table-column><el-table-column label="结果" width="110"><template #default="{row}"><el-tag :type="detailReport.issues.some(issue=>issue.field===row.field)?'warning':'success'">{{ detailReport.issues.some(issue=>issue.field===row.field)?'发现问题':'通过' }}</el-tag></template></el-table-column></el-table><el-table v-if="detailReport.issues.length" :data="detailReport.issues"><el-table-column label="记录" width="80"><template #default="{row}">{{ row.recordIndex+1 }}</template></el-table-column><el-table-column label="字段" prop="fieldName" /><el-table-column label="问题" prop="reason" min-width="200" /><el-table-column label="处理状态" prop="status" width="110" /></el-table></template><el-empty v-else description="此版本尚无质量报告" /></el-collapse-item><el-collapse-item name="history"><template #title><span class="history-title"><el-icon><DocumentCopy /></el-icon>版本历史 <el-tag type="info">{{ versions.length }}</el-tag></span></template><button v-for="item in versions" :key="item.id" class="history-row" :class="{active:item.id===versionId}" @click="versionId=item.id"><span><el-icon><PriceTag /></el-icon>{{ item.release?.tag || `V${item.number}` }}</span><span>{{ item.release?.title || item.type }}</span><el-tag :type="item.status==='已发布'?'success':'info'">{{ item.status }}</el-tag><el-tag v-if="versionApproved(item)" type="success">已获授权</el-tag></button></el-collapse-item></el-collapse>
  <div v-if="version" class="catalog-detail-content"><div class="section-title"><h3><el-icon><Files /></el-icon>内容预览</h3><el-select v-model="versionId" style="width:230px"><el-option v-for="item in versions" :key="item.id" :value="item.id" :label="`${item.release?.tag || `V${item.number}`} · ${(item.totalRecords ?? item.records.length).toLocaleString()}条`" /></el-select></div><section v-if="version.release" class="release-info"><h3>{{ version.release.title }}</h3><p class="release-meta">{{ version.release.publisher }} · {{ version.release.publishedAt }}</p><div class="release-notes">{{ version.release.notes }}</div></section><el-scrollbar max-height="340px"><article v-for="(record,index) in version.records" :key="index" class="record-preview"><small class="muted">第 {{ index+1 }} 条</small><h4>{{ record.question || record.title || '数据内容' }}</h4><img v-if="record.image" :src="record.image" :alt="record.title || record.label || '数据图片'" class="catalog-sample-image" /><el-descriptions v-if="detailFields.length && !record.question && !record.content" :column="2" border><el-descriptions-item v-for="field in detailFields" :key="field.id" :label="field.name+(field.unit?'（'+field.unit+'）':'')">{{ record[field.field] ?? '—' }}</el-descriptions-item></el-descriptions><p v-else>{{ record.correctedAnswer || record.answer || record.content || JSON.stringify(record) }}</p></article></el-scrollbar><div class="dialog-actions"><el-button v-if="owned(selected) && allowed('edit',selected.id)" @click="editDataset"><el-icon><EditPen /></el-icon>在项目中管理</el-button><template v-if="version.status==='已发布'"><el-button v-if="!owned(selected) && !downloadable" type="primary" @click="apply"><el-icon><DocumentChecked /></el-icon>申请使用此版本</el-button><el-button v-else-if="downloadable" type="primary" @click="downloadVersion(version)"><el-icon><Download /></el-icon>下载此版本</el-button></template></div><p v-if="!owned(selected) && !downloadable && version.status==='已发布'" class="muted">使用授权对应具体版本，其他版本需要单独申请。</p></div><el-empty v-else description="暂无数据集版本，先在项目中建设数据" /></template></el-drawer>
  <FormDialog v-model="formOpen" title="申请使用数据" :fields="requestFields" :initial="{applicant:state.role}" confirm-text="提交申请" @save="submit" />
</template>
